import{_ as a,o as s,c as e,a6 as n}from"./chunks/framework.BrkgobfX.js";const c=JSON.parse('{"title":"第十一章总结","description":"从 Bit 到 AGI · 第十一章：工程化（Serving） · 生产部署全景回顾","frontmatter":{"title":"第十一章总结","description":"从 Bit 到 AGI · 第十一章：工程化（Serving） · 生产部署全景回顾","source":"https://daiw.org/manual/bit-to-agi/11-engineering/chapter-summary"},"headers":[],"relativePath":"manual/llm/bit-to-agi/11-engineering/chapter-summary.md","filePath":"manual/llm/bit-to-agi/11-engineering/chapter-summary.md"}'),r={name:"manual/llm/bit-to-agi/11-engineering/chapter-summary.md"};function i(l,t,o,d,p,g){return s(),e("div",null,[...t[0]||(t[0]=[n(`<h1 id="第十一章总结" tabindex="-1">第十一章总结 <a class="header-anchor" href="#第十一章总结" aria-label="Permalink to &quot;第十一章总结&quot;">​</a></h1><blockquote><p>从 Bit 到 AGI · 第十一章：工程化（Serving） · 生产部署全景回顾</p></blockquote><p>本章把「能跑的模型」变成「能扛流量的服务」。核心不是某个工具名，而是<strong>可量化的生产尺子</strong>：吞吐（tok/s、QPS）、体验（TTFT、TPOT）、可靠性（P95/P99、错误预算）和经济学（$/1M tokens）。</p><h2 id="推理引擎怎么选" tabindex="-1">推理引擎怎么选 <a class="header-anchor" href="#推理引擎怎么选" aria-label="Permalink to &quot;推理引擎怎么选&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>首选</th><th>典型数字（8B，A100）</th></tr></thead><tbody><tr><td>通用高 QPS 对话</td><td>vLLM</td><td>~3 000 tok/s，TTFT ~200 ms</td></tr><tr><td>RAG / 共享长 prefix</td><td>SGLang</td><td>prefix 命中 TTFT ~120 ms</td></tr><tr><td>H100 极致性能、可维护编译 CI</td><td>TensorRT-LLM FP8/INT4</td><td>~5 000～6 800 tok/s</td></tr><tr><td>训练栈一体、HF checkpoint 直出</td><td>DeepSpeed FastGen</td><td>~2 900 tok/s</td></tr></tbody></table><p>70B 级通常 <strong>TP=4</strong>，吞吐 <strong>~900～2 200 tok/s</strong>，TTFT <strong>1～1.4 s</strong>（2K input）——容量规划按 <strong>P95 并发</strong> 而非峰值 QPS 估算。</p><h2 id="编排与平台栈" tabindex="-1">编排与平台栈 <a class="header-anchor" href="#编排与平台栈" aria-label="Permalink to &quot;编排与平台栈&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TB</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  GW[Gateway 鉴权限流] --&gt; LM[LiteLLM 路由预算]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  LM --&gt; K8S[K8s Service]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  K8S --&gt; V[vLLM / SGLang Pod]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  V --&gt; OBS[Prometheus OTel]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  OBS --&gt; AS[KEDA Autoscale]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  REG[Model Registry] --&gt; V</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  AB[A/B Canary] --&gt; GW</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><ul><li><strong>Ray</strong>：多 replica + CPU/GPU 混合 pipeline，3 副本约 <strong>3× QPS</strong> 线性区</li><li><strong>Kubernetes</strong>：GPU 调度、readiness <strong>≥120 s</strong>（8B load）、70B TP 宜蓝绿</li><li><strong>LiteLLM + Gateway</strong>：OpenAI 形状统一路由；Gateway 全站限流防 TTFT 崩到 <strong>&gt;8 s</strong></li><li><strong>可观测性</strong>：盯 <code>num_requests_waiting</code>、<code>gpu_cache_usage_perc</code>、TTFT histogram</li><li><strong>Autoscaling</strong>：绑 vLLM 队列，<code>minReplicas ≥ 2</code>，冷启动 <strong>3～5 min</strong></li><li><strong>Registry + A/B + 成本</strong>：immutable version、sticky 分流、团队 budget <strong>$300/月</strong> 级封顶</li></ul><h2 id="训练并行与-serving-的衔接" tabindex="-1">训练并行与 Serving 的衔接 <a class="header-anchor" href="#训练并行与-serving-的衔接" aria-label="Permalink to &quot;训练并行与 Serving 的衔接&quot;">​</a></h2><p>Megatron <strong>TP × PP × DP</strong> 训出 100B+；DeepSpeed <strong>ZeRO-3</strong> 让 70B 全参微调落在 8×A100。Serving 不跑 Megatron——checkpoint <strong>合并 → HF → vLLM/TRT-LLM</strong>，<strong>TP 度数尽量一致</strong>。</p><h2 id="成本锚点-100-m-tokens-月-量级" tabindex="-1">成本锚点（100 M tokens/月，量级） <a class="header-anchor" href="#成本锚点-100-m-tokens-月-量级" aria-label="Permalink to &quot;成本锚点（100 M tokens/月，量级）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方案</th><th>$/1M tokens</th></tr></thead><tbody><tr><td>自托管 8B vLLM（1×A100）</td><td>~$22</td></tr><tr><td>高阶闭源 API（多轮综合折算）</td><td>~$150</td></tr><tr><td>混合 80/20 + prefix cache + INT4</td><td>~$15～52</td></tr></tbody></table><p>FinOps 每周看 Top 消耗；组合优化常见 <strong>-60%～70%</strong>。</p><h2 id="常见坑回顾" tabindex="-1">常见坑回顾 <a class="header-anchor" href="#常见坑回顾" aria-label="Permalink to &quot;常见坑回顾&quot;">​</a></h2><ol><li>用 CPU HPA 扩 GPU 服务 → 排队爆表</li><li>scale to zero → 冷启动 <strong>90 s</strong> 首请求超时</li><li>按 request 做 A/B → 多轮对话失忆</li><li>log 全量 prompt → 合规与存储双爆</li><li>offline MMLU +0.6 直接全量 → 线上解决率可能反降</li></ol><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>工程化解决「模型怎么稳定便宜地跑」。第十二章 <a href="/Front2Full/manual/llm/bit-to-agi/12-future">未来</a> 转向 Agent、工具调用、世界模型与 AGI 路线图——Serving 栈是 Agent 系统的底座，延迟与成本会直接约束「能跑多复杂的 agent loop」。</p><p>→ 下一章：<a href="/Front2Full/manual/llm/bit-to-agi/12-future">第十二章：未来</a></p>`,19)])])}const u=a(r,[["render",i]]);export{c as __pageData,u as default};
